import re

orig_weights = wsp.edit.snapshot(model.hf_model.named_parameters())
print("Saved snapshot of", len(orig_weights), "tensors.")

def parse_generate_output(text):
    # Format is:
    # (forward passes left: N)\n[0] ... \n\n[1] ...
    lines = text.split("\n", 1)
    header = lines[0]
    body = lines[1] if len(lines) > 1 else ""
    parts = re.split(r'\n?\n?\[(\d+)\] ', "\n" + body)
    # parts[0] is before [0], then pairs of (idx, content)
    outputs = {}
    for k in range(1, len(parts), 2):
        idx = int(parts[k])
        content = parts[k+1]
        hit_max = content.startswith("(hit max_new_tokens) ")
        if hit_max:
            content = content[len("(hit max_new_tokens) "):]
        outputs[idx] = {"text": content, "hit_max": hit_max}
    return header, outputs

def normalize_ans(s):
    s = str(s).strip()
    s = s.replace("$", "").replace("\\%", "").replace("%", "").replace(",", "").replace(" ", "")
    s = re.sub(r'\\text\{([^}]*)\}', r'\1', s)
    s = re.sub(r'\\dfrac', r'\\frac', s)
    s = re.sub(r'\\tfrac', r'\\frac', s)
    if s.endswith("."):
        s = s[:-1]
    # normalize simple fractions like 2/3 to \frac{2}{3}
    m = re.match(r'^(-?\d+)/(\d+)$', s)
    if m:
        s = f"\\frac{{{m.group(1)}}}{{{m.group(2)}}}"
    # normalize .0 or .00
    try:
        val = float(s)
        if val == int(val):
            return str(int(val))
        return str(val)
    except:
        pass
    return s

def extract_answer(text):
    # 1. Check \boxed{...}
    boxed = re.findall(r'\\boxed\{((?:[^{}]|\{[^{}]*\})*)\}', text)
    if boxed:
        return normalize_ans(boxed[-1])
    # 2. Check **Answer:** or Answer: at end
    m = re.findall(r'(?:Answer|Conclusion)[:\s\*]*([^\n]+)', text, flags=re.IGNORECASE)
    # Look in the last 300 chars for bolded answer **...**
    tail = text[-400:] if len(text) > 400 else text
    bolds = re.findall(r'\*\*([^\*]+)\*\*', tail)
    if bolds:
        # Check if bold contains a number or fraction
        for b in reversed(bolds):
            b_clean = b.strip().rstrip(".")
            if any(c.isdigit() for c in b_clean):
                # extract fraction or number from b_clean
                fm = re.search(r'\\frac\{[^{}]+\}\{[^{}]+\}|-?\d+(?:,\d{3})*(?:\.\d+)?(?:/\d+)?', b_clean)
                if fm:
                    return normalize_ans(fm.group(0))
    # Look for last fraction or number in tail
    fm = re.findall(r'\\frac\{[^{}]+\}\{[^{}]+\}|-?\d+(?:,\d{3})*(?:\.\d+)?(?:/\d+)?', tail)
    if fm:
        return normalize_ans(fm[-1])
    return ""

def check_correct(pred_text, gold):
    pred = extract_answer(pred_text)
    gold_norm = normalize_ans(gold)
    return pred == gold_norm, pred, gold_norm

